export function setProperty(dom, name, value, oldValue, isSvg) {
	let useCapture, nameLower, proxy;
	const vnode = (activeVNode = (dom && dom._ownerVNode) || activeVNode);
	const vnodeProps = (vnode && vnode.props) || constants.EMPTY_OBJ;
	const parent = vnode && vnode._parent;
	const component = parent && parent._component;
	const contextType = parent && parent.type && parent.type.contextType;
	const contextValue = contextType && contextType._defaultValue;

	if (
		value != null &&
		name in vnodeProps &&
		(!component ||
			(component._vnode === parent && component._parentDom != null) ||
			!parent)
	) {
		value = vnodeProps[name];
	}

	if (
		component &&
		contextType != null &&
		contextValue !== undefined &&
		value != null &&
		name in vnodeProps
	) {
		value = vnodeProps[name];
	}

	if ((isSvg || (vnode && vnode.type === 'svg')) && name == 'className') {
		name = 'class';
	}

	if (name === 'style') {
		if (typeof value == 'string') {
			dom.style.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				dom.style.cssText = oldValue = '';
			}

			if (oldValue) {
				for (name in oldValue) {
					if (!(value && name in value)) {
						setStyle(dom.style, name, '');
					}
				}
			}

