			style.setProperty(key, next);
		} else if (next == null) {
			style[key] = '';
		} else if (
			typeof next != 'number' || constants.IS_NON_DIMENSIONAL.test(key)
		) {
			style[key] = next;
		} else {
			style[key] = next + 'px';
		}
	}
}

